package main

import (
	"crypto/rand"
	"fmt"
	"strings"

	"crypto/ecdh"
)

// minimal bech32 (BIP-173)
const charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

func polymod(values []byte) uint32 {
	chk := uint32(1)
	gen := []uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	for _, v := range values {
		top := chk >> 25
		chk = (chk & 0x1ffffff) << 5 ^ uint32(v)
		for i := 0; i < 5; i++ {
			if (top>>uint(i))&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func hrpExpand(hrp string) []byte {
	out := []byte{}
	for _, c := range hrp {
		out = append(out, byte(c>>5))
	}
	out = append(out, 0)
	for _, c := range hrp {
		out = append(out, byte(c&31))
	}
	return out
}

func convertBits(data []byte, from, to uint, pad bool) []byte {
	acc := uint32(0)
	bits := uint(0)
	out := []byte{}
	maxv := uint32((1 << to) - 1)
	for _, b := range data {
		acc = acc<<from | uint32(b)
		bits += from
		for bits >= to {
			bits -= to
			out = append(out, byte(acc>>bits&maxv))
		}
	}
	if pad && bits > 0 {
		out = append(out, byte(acc<<(to-bits)&maxv))
	}
	return out
}

func bech32Encode(hrp string, data []byte) string {
	values := convertBits(data, 8, 5, true)
	merged := append(hrpExpand(hrp), values...)
	merged = append(merged, 0, 0, 0, 0, 0, 0)
	mod := polymod(merged) ^ 1
	checksum := make([]byte, 6)
	for i := 0; i < 6; i++ {
		checksum[i] = byte(mod >> uint(5*(5-i)) & 31)
	}
	var sb strings.Builder
	sb.WriteString(hrp)
	sb.WriteString("1")
	for _, v := range append(values, checksum...) {
		sb.WriteByte(charset[v])
	}
	return sb.String()
}

func main() {
	priv, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		panic(err)
	}
	pub := priv.PublicKey().Bytes()
	fmt.Println("AGE-SECRET-KEY-" + strings.ToUpper(bech32Encode("age-secret-key-", priv.Bytes())))
	fmt.Println(bech32Encode("age", pub))
}
EOF
