// Package bech32 implements the Bech32 encoding (BIP-0173), without
// enforcing the 90-character length limit, as required for long age keys.
package bech32

import (
	"fmt"
	"strings"
)

const charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

var charsetRev [128]int8

func init() {
	for i := range charsetRev {
		charsetRev[i] = -1
	}
	for i, c := range []byte(charset) {
		charsetRev[c] = int8(i)
	}
}

func polymod(values []byte) uint32 {
	chk := uint32(1)
	gen := []uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	for _, v := range values {
		top := chk >> 25
		chk = (chk & 0x1ffffff) << 5 ^ uint32(v)
		for i := 0; i < 5; i++ {
			if (top>>uint(i))&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func hrpExpand(hrp string) []byte {
	out := make([]byte, 0, len(hrp)*2+1)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]>>5)
	}
	out = append(out, 0)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]&31)
	}
	return out
}

func verifyChecksum(hrp string, data []byte) bool {
	return polymod(append(hrpExpand(hrp), data...)) == 1
}

func createChecksum(hrp string, data []byte) []byte {
	values := append(hrpExpand(hrp), data...)
	values = append(values, 0, 0, 0, 0, 0, 0)
	mod := polymod(values) ^ 1
	ret := make([]byte, 6)
	for i := 0; i < 6; i++ {
		ret[i] = byte(mod>>uint(5*(5-i))) & 31
	}
	return ret
}

func convertBits(data []byte, fromBits, toBits uint, pad bool) ([]byte, error) {
	acc := uint32(0)
	bits := uint(0)
	out := []byte{}
	maxv := uint32((1<<toBits)-1)
	maxAcc := uint32((1 << (fromBits + toBits - 1)) - 1)
	for _, b := range data {
		if uint32(b)>>fromBits != 0 {
			return nil, fmt.Errorf("invalid data byte")
		}
		acc = ((acc << fromBits) | uint32(b)) & maxAcc
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			out = append(out, byte(acc>>bits)&byte(maxv))
		}
	}
	if pad {
		if bits > 0 {
			out = append(out, byte(acc<<(toBits-bits))&byte(maxv))
		}
	} else {
		if bits >= fromBits {
			return nil, fmt.Errorf("invalid incomplete group")
		}
		if byte(acc<<(toBits-bits))&byte(maxv) != 0 {
			return nil, fmt.Errorf("non-zero padding")
		}
	}
	return out, nil
}

// Encode encodes data with the given human-readable prefix.
func Encode(hrp string, data []byte) (string, error) {
	values, err := convertBits(data, 8, 5, true)
	if err != nil {
		return "", err
	}
	if len(hrp) < 1 {
		return "", fmt.Errorf("invalid hrp")
	}
	for i := 0; i < len(hrp); i++ {
		if hrp[i] < 33 || hrp[i] > 126 {
			return "", fmt.Errorf("invalid hrp character")
		}
	}
	hrp = strings.ToLower(hrp)
	checksum := createChecksum(hrp, values)
	var sb strings.Builder
	sb.WriteString(hrp)
	sb.WriteString("1")
	for _, v := range append(values, checksum...) {
		sb.WriteByte(charset[v])
	}
	return sb.String(), nil
}

// Decode decodes a Bech32 string, returning the human-readable prefix and
// the data.
func Decode(s string) (string, []byte, error) {
	if len(s) < 8 {
		return "", nil, fmt.Errorf("invalid bech32 string length %d", len(s))
	}
	lower := strings.ToLower(s)
	upper := strings.ToUpper(s)
	if s != lower && s != upper {
		return "", nil, fmt.Errorf("string not all lowercase or all uppercase")
	}
	s = lower
	one := strings.LastIndexByte(s, '1')
	if one < 1 || one+7 > len(s) {
		return "", nil, fmt.Errorf("invalid index of 1")
	}
	hrp := s[:one]
	for i := 0; i < len(hrp); i++ {
		if hrp[i] < 33 || hrp[i] > 126 {
			return "", nil, fmt.Errorf("invalid character human-readable part")
		}
	}
	data := []byte{}
	for i := one + 1; i < len(s); i++ {
		c := s[i]
		if c > 127 || charsetRev[c] == -1 {
			return "", nil, fmt.Errorf("invalid character not part of charset: %v", c)
		}
		data = append(data, byte(charsetRev[c]))
	}
	if !verifyChecksum(hrp, data) {
		return "", nil, fmt.Errorf("invalid checksum")
	}
	decoded, err := convertBits(data[:len(data)-6], 5, 8, false)
	if err != nil {
		return "", nil, err
	}
	return hrp, decoded, nil
}

// DecodeNoLimit is like Decode; kept for API clarity (no length limit is
// enforced by Decode).
func DecodeNoLimit(s string) (string, []byte, error) {
	return Decode(s)
}

