package primitives

import (
	"crypto/cipher"
	"encoding/binary"
	"errors"

	"math/bits"
)

const (
	chachaKeySize   = 32
	chachaNonceSize = 12
)

var errOpen = errors.New("chacha20poly1305: message authentication failed")

func quarterRound(s *[16]uint32, a, b, c, d int) {
	s[a] += s[b]
	s[d] ^= s[a]
	s[d] = bits.RotateLeft32(s[d], 16)
	s[c] += s[d]
	s[b] ^= s[c]
	s[b] = bits.RotateLeft32(s[b], 12)
	s[a] += s[b]
	s[d] ^= s[a]
	s[d] = bits.RotateLeft32(s[d], 8)
	s[c] += s[d]
	s[b] ^= s[c]
	s[b] = bits.RotateLeft32(s[b], 7)
}

func chacha20Block(key [8]uint32, counter uint32, nonce [3]uint32) [16]uint32 {
	var state [16]uint32
	state[0] = 0x61707865
	state[1] = 0x3320646e
	state[2] = 0x79622d32
	state[3] = 0x6b206574
	copy(state[4:12], key[:])
	state[12] = counter
	copy(state[13:16], nonce[:])
	working := state
	for i := 0; i < 10; i++ {
		quarterRound(&working, 0, 4, 8, 12)
		quarterRound(&working, 1, 5, 9, 13)
		quarterRound(&working, 2, 6, 10, 14)
		quarterRound(&working, 3, 7, 11, 15)
		quarterRound(&working, 0, 5, 10, 15)
		quarterRound(&working, 1, 6, 11, 12)
		quarterRound(&working, 2, 7, 8, 13)
		quarterRound(&working, 3, 4, 9, 14)
	}
	var out [16]uint32
	for i := 0; i < 16; i++ {
		out[i] = working[i] + state[i]
	}
	return out
}

func loadKey(key []byte) [8]uint32 {
	var k [8]uint32
	for i := 0; i < 8; i++ {
		k[i] = binary.LittleEndian.Uint32(key[i*4:])
	}
	return k
}

func loadNonce(nonce []byte) [3]uint32 {
	var n [3]uint32
	for i := 0; i < 3; i++ {
		n[i] = binary.LittleEndian.Uint32(nonce[i*4:])
	}
	return n
}

// chacha20XORKeyStream encrypts (or decrypts) src with the given counter.
func chacha20XORKeyStream(dst, src []byte, key [8]uint32, counter uint32, nonce [3]uint32) {
	for len(src) > 0 {
		block := chacha20Block(key, counter, nonce)
		counter++
		n := len(src)
		if n > 64 {
			n = 64
		}
		var ks [64]byte
		for i := 0; i < 16; i++ {
			binary.LittleEndian.PutUint32(ks[i*4:], block[i])
		}
		for i := 0; i < n; i++ {
			dst[i] = src[i] ^ ks[i]
		}
		dst = dst[n:]
		src = src[n:]
	}
}

// Poly1305 implementation (RFC 8439), 64-bit generic version.

type poly1305 struct {
	r [2]uint64
	h [3]uint64
	s [2]uint64
	buf [16]byte
	off int
}

const poly1305TagSize = 16

func newPoly1305(key [32]byte) *poly1305 {
	p := &poly1305{}
	p.r[0] = binary.LittleEndian.Uint64(key[0:8]) & 0x0ffffffc0fffffff
	p.r[1] = binary.LittleEndian.Uint64(key[8:16]) & 0x0ffffffc0ffffffc
	p.s[0] = binary.LittleEndian.Uint64(key[16:24])
	p.s[1] = binary.LittleEndian.Uint64(key[24:32])
	return p
}

func (p *poly1305) Write(m []byte) (int, error) {
	n := len(m)
	if p.off > 0 {
		d := copy(p.buf[p.off:], m)
		p.off += d
		m = m[d:]
		if p.off == 16 {
			poly1305Block(p, p.buf[:], 1)
			p.off = 0
		}
	}
	for len(m) >= 16 {
		poly1305Block(p, m[:16], 1)
		m = m[16:]
	}
	if len(m) > 0 {
		p.off = copy(p.buf[:], m)
	}
	return n, nil
}

func poly1305Block(p *poly1305, m []byte, hibit uint64) {
	r0, r1 := p.r[0], p.r[1]
	h0, h1, h2 := p.h[0], p.h[1], p.h[2]
	m0 := binary.LittleEndian.Uint64(m[0:8])
	m1 := binary.LittleEndian.Uint64(m[8:16])
	var c uint64
	h0, c = bits.Add64(h0, m0, 0)
	h1, c = bits.Add64(h1, m1, c)
	h2, _ = bits.Add64(h2, hibit, c)

	// h *= r mod 2^130 - 5
	h0r0hi, h0r0lo := bits.Mul64(h0, r0)
	h1r0hi, h1r0lo := bits.Mul64(h1, r0)
	h2r0hi, h2r0lo := bits.Mul64(h2, r0)
	h0r1hi, h0r1lo := bits.Mul64(h0, r1)
	h1r1hi, h1r1lo := bits.Mul64(h1, r1)
	h2r1hi, h2r1lo := bits.Mul64(h2, r1)

	// r0*r0
	m00h, m00l := h0r0hi, h0r0lo
	// r0*r1*2 (mod reduction of high part)
	// Compute full 256-bit product then reduce mod 2^130-5.
	// t = h*r: t0..t4 (64-bit limbs)
	// h = h0 + h1*2^64 + h2*2^128
	// r = r0 + r1*2^64
	// t0 = h0*r0
	// t1 = h0*r1 + h1*r0
	// t2 = h1*r1 + h2*r0
	// t3 = h2*r1
	// (values above 2^130 folded with *5 since 2^130 = 5 mod p)
	t0lo, t0hi := m00l, m00h
	// t1
	t1lo, c := bits.Add64(h0r1lo, h1r0lo, 0)
	t1hi, c2 := bits.Add64(h0r1hi, h1r0hi, c)
	_ = c2
	// t2
	t2lo, c := bits.Add64(h1r1lo, h2r0lo, 0)
	t2hi, c2 := bits.Add64(h1r1hi, h2r0hi, c)
	t2hi += c2
