	// use 128-bit accumulation via extra limb tracking.
	// t = t0 + t1<<64 + t2<<128 + t3<<192 (each ti is 128-bit)
	// Collect into limbs L0..L3 (64-bit), L4 (few bits)
	L0 := t0lo
	L1, c := bits.Add64(t0hi, t1lo, 0)
	L2, c := bits.Add64(t1hi+c, t2lo, 0) // t1hi <= ~2 so c fits
	L3, c := bits.Add64(t2hi+c, t3lo, 0)
	L4 := t3hi + c

	// Fold bits >= 2^130: split L2/L3/L4 at bit 130 (i.e. 2 bits into L2)
	// h2 keeps low 2 bits of L2; fold (L2>>2, L3, L4) * 5
	h0, h1 = L0, L1
	h2 = L2 & 3
	f0 := L2 >> 2
	f1 := L3
	f2 := L4
	// fold = (f2 f1 f0) * 5 = fold*4 + fold
