	s0, c = bits.Add64(s0, f0, 0)
	s1, c = bits.Add64(s1, f1, c)
	s2, c = bits.Add64(s2, f2, c)
	s3 += c
	_ = f0h
	_ = f1h
	_ = f2h
	_ = f2l
	// fold value now in s0..s3 (small). Add into h.
	h0, c = bits.Add64(h0, s0, 0)
	h1, c = bits.Add64(h1, s1, 0)
	h2, _ = bits.Add64(h2, s2+c, 0)
	// h2 could still exceed 3 slightly; fold again if needed (rare, small)
	if h2 > 3 || s3 > 0 {
		// fold h2>>2 and s3 * 5
		extra := (h2 >> 2) + (s3 << 62) // s3 is 0 or 1
		h2 &= 3
		h0, c = bits.Add64(h0, extra*5, 0)
		h1, c = bits.Add64(h1, 0, c)
		h2 += c
	}
	p.h[0], p.h[1], p.h[2] = h0, h1, h2
}

func (p *poly1305) Sum(out []byte) []byte {
	if p.off > 0 {
		for i := p.off; i < 16; i++ {
			p.buf[i] = 0
		}
		poly1305Block(p, p.buf[:], 0) // partial block: no hibit, but 1 byte appended at len
		p.off = 0
	}
	h0, h1, h2 := p.h[0], p.h[1], p.h[2]
	// compute h + -p (i.e., h - (2^130-5)) and select if no borrow
	// p = 2^130-5 → -p mod 2^192-ish: subtract and check
	// g = h + 5 - 2^130
	g0, c := bits.Add64(h0, 5, 0)
	g1, c := bits.Add64(h1, 0, c)
	g2, _ := bits.Add64(h2, 0, c)
	// if g2 >= 4 (i.e. h+5 >= 2^130), use g
	mask := uint64(0)
	if g2 >= 4 {
		mask = ^uint64(0)
	}
	h0 = (h0 &^ mask) | (g0 & mask)
	h1 = (h1 &^ mask) | (g1 & mask)
	// add s
	h0, c = bits.Add64(h0, p.s[0], 0)
	h1, _ = bits.Add64(h1, p.s[1], c)
	var tag [16]byte
	binary.LittleEndian.PutUint64(tag[0:8], h0)
	binary.LittleEndian.PutUint64(tag[8:16], h1)
	return append(out, tag[:]...)
}

