// Package primitives implements the cryptographic primitives needed by the
// age file format that are not available in the Go standard library:
// ChaCha20, Poly1305, the ChaCha20-Poly1305 AEAD (RFC 8439), HKDF
// (RFC 5869), and scrypt (RFC 7914).
package primitives

import (
	"crypto/cipher"
	"encoding/binary"
	"errors"
	"math/bits"
)

const (
	chachaKeySize   = 32
	chachaNonceSize = 12
)

var errOpen = errors.New("chacha20poly1305: message authentication failed")

func quarterRound(s *[16]uint32, a, b, c, d int) {
	s[a] += s[b]
	s[d] ^= s[a]
	s[d] = bits.RotateLeft32(s[d], 16)
	s[c] += s[d]
	s[b] ^= s[c]
	s[b] = bits.RotateLeft32(s[b], 12)
	s[a] += s[b]
	s[d] ^= s[a]
	s[d] = bits.RotateLeft32(s[d], 8)
	s[c] += s[d]
	s[b] ^= s[c]
	s[b] = bits.RotateLeft32(s[b], 7)
}

func chacha20Block(key *[8]uint32, counter uint32, nonce *[3]uint32) [16]uint32 {
	var state [16]uint32
	state[0] = 0x61707865
	state[1] = 0x3320646e
	state[2] = 0x79622d32
	state[3] = 0x6b206574
	copy(state[4:12], key[:])
	state[12] = counter
	copy(state[13:16], nonce[:])
	working := state
	for i := 0; i < 10; i++ {
		quarterRound(&working, 0, 4, 8, 12)
		quarterRound(&working, 1, 5, 9, 13)
		quarterRound(&working, 2, 6, 10, 14)
		quarterRound(&working, 3, 7, 11, 15)
		quarterRound(&working, 0, 5, 10, 15)
		quarterRound(&working, 1, 6, 11, 12)
		quarterRound(&working, 2, 7, 8, 13)
		quarterRound(&working, 3, 4, 9, 14)
	}
	var out [16]uint32
	for i := 0; i < 16; i++ {
		out[i] = working[i] + state[i]
	}
	return out
}

func loadKey(key []byte) [8]uint32 {
	var k [8]uint32
	for i := 0; i < 8; i++ {
		k[i] = binary.LittleEndian.Uint32(key[i*4:])
	}
	return k
}

func loadNonce(nonce []byte) [3]uint32 {
	var n [3]uint32
	for i := 0; i < 3; i++ {
		n[i] = binary.LittleEndian.Uint32(nonce[i*4:])
	}
	return n
}

func chacha20XORKeyStream(dst, src []byte, key *[8]uint32, counter uint32, nonce *[3]uint32) {
	for len(src) > 0 {
		block := chacha20Block(key, counter, nonce)
		counter++
		n := len(src)
		if n > 64 {
			n = 64
		}
		var ks [64]byte
		for i := 0; i < 16; i++ {
			binary.LittleEndian.PutUint32(ks[i*4:], block[i])
		}
		for i := 0; i < n; i++ {
			dst[i] = src[i] ^ ks[i]
		}
		dst = dst[n:]
		src = src[n:]
	}
}

// Poly1305 one-time authenticator (RFC 8439), based on the public domain
// poly1305-donna 32-bit algorithm.

type poly1305 struct {
	r   [5]uint32
	h   [5]uint32
	pad [4]uint32
	buf [16]byte
	off int
}

func newPoly1305(key []byte) *poly1305 {
	p := &poly1305{}
	t0 := binary.LittleEndian.Uint32(key[0:])
	t1 := binary.LittleEndian.Uint32(key[4:])
	t2 := binary.LittleEndian.Uint32(key[8:])
	t3 := binary.LittleEndian.Uint32(key[12:])
	p.r[0] = t0 & 0x3ffffff
	p.r[1] = (t0>>26 | t1<<6) & 0x3ffff03
	p.r[2] = (t1>>20 | t2<<12) & 0x3ffc0ff
	p.r[3] = (t2>>14 | t3<<18) & 0x3f03fff
	p.r[4] = t3>>8 & 0x00fffff
	p.pad[0] = binary.LittleEndian.Uint32(key[16:])
	p.pad[1] = binary.LittleEndian.Uint32(key[20:])
	p.pad[2] = binary.LittleEndian.Uint32(key[24:])
	p.pad[3] = binary.LittleEndian.Uint32(key[28:])
	return p
}

func (p *poly1305) block(m []byte, hibit uint32) {
	r0, r1, r2, r3, r4 := p.r[0], p.r[1], p.r[2], p.r[3], p.r[4]
	s1, s2, s3, s4 := r1*5, r2*5, r3*5, r4*5
	h0, h1, h2, h3, h4 := p.h[0], p.h[1], p.h[2], p.h[3], p.h[4]

	h0 += binary.LittleEndian.Uint32(m[0:]) & 0x3ffffff
	h1 += (binary.LittleEndian.Uint32(m[3:]) >> 2) & 0x3ffffff
	h2 += (binary.LittleEndian.Uint32(m[6:]) >> 4) & 0x3ffffff
	h3 += (binary.LittleEndian.Uint32(m[9:]) >> 6) & 0x3ffffff
	h4 += (binary.LittleEndian.Uint32(m[12:]) >> 8) | hibit

	d0 := uint64(h0)*uint64(r0) + uint64(h1)*uint64(s4) + uint64(h2)*uint64(s3) + uint64(h3)*uint64(s2) + uint64(h4)*uint64(s1)
	d1 := uint64(h0)*uint64(r1) + uint64(h1)*uint64(r0) + uint64(h2)*uint64(s4) + uint64(h3)*uint64(s3) + uint64(h4)*uint64(s2)
	d2 := uint64(h0)*uint64(r2) + uint64(h1)*uint64(r1) + uint64(h2)*uint64(r0) + uint64(h3)*uint64(s4) + uint64(h4)*uint64(s3)
	d3 := uint64(h0)*uint64(r3) + uint64(h1)*uint64(r2) + uint64(h2)*uint64(r1) + uint64(h3)*uint64(r0) + uint64(h4)*uint64(s4)
	d4 := uint64(h0)*uint64(r4) + uint64(h1)*uint64(r3) + uint64(h2)*uint64(r2) + uint64(h3)*uint64(r1) + uint64(h4)*uint64(r0)

	c := d0 >> 26
	h0 = uint32(d0) & 0x3ffffff
	d1 += c
	c = d1 >> 26
	h1 = uint32(d1) & 0x3ffffff
	d2 += c
	c = d2 >> 26
	h2 = uint32(d2) & 0x3ffffff
	d3 += c
	c = d3 >> 26
	h3 = uint32(d3) & 0x3ffffff
	d4 += c
	c = d4 >> 26
	h4 = uint32(d4) & 0x3ffffff
	h0 += uint32(c) * 5
	c = uint64(h0 >> 26)
	h0 &= 0x3ffffff
	h1 += uint32(c)

	p.h[0], p.h[1], p.h[2], p.h[3], p.h[4] = h0, h1, h2, h3, h4
}

func (p *poly1305) Write(m []byte) (int, error) {
	n := len(m)
	if p.off > 0 {
		d := copy(p.buf[p.off:], m)
		p.off += d
		m = m[d:]
		if p.off == 16 {
			p.block(p.buf[:], 1<<24)
			p.off = 0
		}
	}
	for len(m) >= 16 {
		p.block(m[:16], 1<<24)
		m = m[16:]
	}
	if len(m) > 0 {
		p.off = copy(p.buf[:], m)
	}
	return n, nil
}

func (p *poly1305) Sum() [16]byte {
	if p.off > 0 {
		p.buf[p.off] = 1
		for i := p.off + 1; i < 16; i++ {
			p.buf[i] = 0
		}
		p.block(p.buf[:], 0)
		p.off = 0
	}
	h0, h1, h2, h3, h4 := p.h[0], p.h[1], p.h[2], p.h[3], p.h[4]
	// full carry
	c := h1 >> 26
	h1 &= 0x3ffffff
	h2 += c
	c = h2 >> 26
	h2 &= 0x3ffffff
	h3 += c
	c = h3 >> 26
	h3 &= 0x3ffffff
	h4 += c
	c = h4 >> 26
	h4 &= 0x3ffffff
	h0 += c * 5
	c = h0 >> 26
	h0 &= 0x3ffffff
	h1 += c
