	}
	n := loadNonce(nonce)
	// Poly1305 key from counter 0.
	var otk [32]byte
	block := chacha20Block(&a.key, 0, &n)
	for i := 0; i < 8; i++ {
		binary.LittleEndian.PutUint32(otk[i*4:], block[i])
