	if len(nonce) != chachaNonceSize {
		panic("chacha20poly1305: bad nonce length")
	}
	if len(ciphertext) < 16 {
		return nil, errOpen
	}
	n := loadNonce(nonce)
	var otk [32]byte
	block := chacha20Block(&a.key, 0, &n)
	for i := 0; i < 8; i++ {
		binary.LittleEndian.PutUint32(otk[i*4:], block[i])
