package primitives

import (
	"crypto/hmac"
	"crypto/sha256"
	"hash"
)

// HKDF-SHA256 (RFC 5869), single-shot expand limited to < 256*32 bytes.
func HKDF(secret, salt, info []byte, length int) []byte {
	var prk [32]byte
	if salt == nil {
		salt = make([]byte, sha256.Size)
	}
	h := hmac.New(sha256.New, salt)
	h.Write(secret)
	copy(prk[:], h.Sum(nil))

	var out, t []byte
	for i := 1; len(out) < length; i++ {
		h = hmac.New(sha256.New, prk[:])
		h.Write(t)
		h.Write(info)
		h.Write([]byte{byte(i)})
		t = h.Sum(nil)
		out = append(out, t...)
	}
	return out[:length]
}

// scrypt password-based KDF (RFC 7914).
func Scrypt(password, salt []byte, N, r, p, keyLen int) ([]byte, error) {
	if N <= 1 || N&(N-1) != 0 {
		return nil, errInvalidScryptN
	}
	xy := make([]uint32, 64*r)
	v := make([]uint32, 32*N*r)
	b := pbkdf2SHA256(password, salt, 1, p*128*r)
	for i := 0; i < p; i++ {
		block := b[i*128*r:]
		var x [32]uint32
		for j := 0; j < 32*r; j++ {
			x[j] = uint32(block[j*4]) | uint32(block[j*4+1])<<8 | uint32(block[j*4+2])<<16 | uint32(block[j*4+3])<<24
		}
		romix(&x, v, xy, N, r)
		for j := 0; j < 32*r; j++ {
			block[j*4+0] = byte(x[j])
			block[j*4+1] = byte(x[j] >> 8)
			block[j*4+2] = byte(x[j] >> 16)
			block[j*4+3] = byte(x[j] >> 24)
		}
	}
	return pbkdf2SHA256(password, b, 1, keyLen), nil
}

type scryptError string

func (e scryptError) Error() string { return string(e) }

const errInvalidScryptN = scryptError("scrypt: N must be a power of 2 greater than 1")

func pbkdf2SHA256(password, salt []byte, iter, keyLen int) []byte {
	prf := hmac.New(sha256.New, password)
	hashLen := prf.Size()
	numBlocks := (keyLen + hashLen - 1) / hashLen
	var buf [4]byte
	dk := make([]byte, 0, numBlocks*hashLen)
	U := make([]byte, 0, len(salt)+4)
	U = append(U, salt...)
	for block := 1; block <= numBlocks; block++ {
		prf.Reset()
		buf[0] = byte(block >> 24)
		buf[1] = byte(block >> 16)
		buf[2] = byte(block >> 8)
		buf[3] = byte(block)
		prf.Write(U[:len(salt)])
		prf.Write(buf[:])
		T := prf.Sum(nil)
		u := T
		for n := 2; n <= iter; n++ {
			prf.Reset()
			prf.Write(u)
			u = prf.Sum(nil)
			for i := range T {
				T[i] ^= u[i]
			}
		}
		dk = append(dk, T...)
	}
	return dk[:keyLen]
}

func romix(x *[32]uint32, v, xy []uint32, N, r int) {
	// x is 32*r words (r blocks of 8 words... actually 64*r bytes = 16*r words? no: 128*r bytes = 32*r words)
	n := 32 * r
	xx := x[:n]
	for i := 0; i < N; i++ {
		copy(v[i*n:(i+1)*n], xx)
		blockMix(xx, xy, r)
	}
	for i := 0; i < N; i++ {
		j := integerify(xx, r) & uint64(N-1)
		for k := 0; k < n; k++ {
			xx[k] ^= v[int(j)*n+k]
		}
