package primitives

import (
	"bytes"
	"encoding/hex"
	"testing"
)

func unhex(s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		panic(err)
	}
	return b
}

// RFC 8439 A.5: Poly1305 one-time authenticator test.
func TestPoly1305(t *testing.T) {
	key := unhex("85d6be7857556d337f4452fe42d506a80103808afb0db2fd4abff6af4149f51b")
	msg := []byte("Cryptographic Forum Research Group")
	var k [32]byte
	copy(k[:], key)
	tag := poly1305Sum(msg, k)
	want := unhex("a8061dc1305136c6c22b8baf0c0127a9")
	if !bytes.Equal(tag[:], want) {
		t.Errorf("got %x, want %x", tag, want)
	}
}

// RFC 8439 2.4.2: ChaCha20 encryption test.
func TestChaCha20(t *testing.T) {
	key := make([]byte, 32)
	for i := range key {
		key[i] = byte(i)
	}
	nonce := unhex("000000000000004a00000000")
	pt := []byte("Ladies and Gentlemen of the class of '99: If I could offer you only one tip for the future, sunscreen would be it.")
	k := loadKey(key)
	n := loadNonce(nonce)
	out := make([]byte, len(pt))
	chacha20XORKeyStream(out, pt, &k, 1, &n)
	want := unhex("6e2e359a2568f98041ba0728dd0d6981e97a7c0f51d12a81169558ca7a1f24c190bd1b6ba106cdcd7a355baf0ac58c835ea657fb08b02ca65c57f7a55c94e73d8bf06d57ab5acaedf9f6b60ecde341b0f50aa5f5be02908a4fb0c4efddbd1fd7")
	if !bytes.Equal(out, want) {
		t.Errorf("got %x", out)
	}
}

// RFC 8439 2.8.2: AEAD test.
func TestAEAD(t *testing.T) {
	key := make([]byte, 32)
	for i := range key {
		key[i] = 0x80 + byte(i)
	}
	nonce := unhex("070000004041424344454647")
	aad := unhex("50515253c0c1c2c3c4c5c6c7")
	pt := []byte("Ladies and Gentlemen of the class of '99: If I could offer you only one tip for the future, sunscreen would be it.")
	a := NewAEAD(key)
	ct := a.Seal(nil, nonce, pt, aad)
	wantTag := unhex("1ae10b594f09e26a7e902ecbd0600691")
	if !bytes.Equal(ct[len(ct)-16:], wantTag) {
		t.Errorf("tag got %x", ct[len(ct)-16:])
	}
	dec, err := a.Open(nil, nonce, ct, aad)
	if err != nil || !bytes.Equal(dec, pt) {
		t.Errorf("open failed: %v", err)
	}
	ct[0] ^= 1
	if _, err := a.Open(nil, nonce, ct, aad); err == nil {
		t.Errorf("expected auth failure")
	}
}

// RFC 5869 test case 1.
func TestHKDF(t *testing.T) {
	ikm := bytes.Repeat([]byte{0x0b}, 22)
	salt := unhex("000102030405060708090a0b0c")
	info := unhex("f0f1f2f3f4f5f6f7f8f9")
	okm := HKDF(ikm, salt, info, 42)
	want := unhex("3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865")
	if !bytes.Equal(okm, want) {
		t.Errorf("got %x", okm)
	}
}

// RFC 7914 scrypt test vector.
func TestScrypt(t *testing.T) {
	dk, err := Scrypt([]byte(""), []byte(""), 16, 1, 1, 64)
	if err != nil {
		t.Fatal(err)
	}
	want := unhex("77d6576238657b203b19ca42c18a0497f16b4844e3074ae8dfdffa3fede21442fcd0069ded0948f8326a753a0fc81f17e8d3e0fb2e0d3628cf35e20c38d18906")
	if !bytes.Equal(dk, want) {
		t.Errorf("got %x", dk)
	}
	dk2, err := Scrypt([]byte("password"), []byte("NaCl"), 1024, 8, 16, 64)
	if err != nil {
		t.Fatal(err)
	}
	want2 := unhex("fdbabe1c9d3472007856e7190d01e9fe7c6ad7cbc8237830e77376634b3731622eaf30d92e22a3886ff109279d9830dac727afb94a83ee6d8360cbdfa2cc0640")
	if !bytes.Equal(dk2, want2) {
		t.Errorf("got %x", dk2)
	}
}

